workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer of the bookshop"

        bookshop = softwareSystem "Bookshop" "An online bookshop" {
            webStore = container "Web Store" "The web store where customers browse and buy books" "Web"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Service"

            customer -> webStore "Browses and buys books" "HTTPS"
            webStore -> orderProcessor "Submits orders" "gRPC"
        }
    }

    views {
        systemContext bookshop "SystemContext" "The system context view of the Bookshop" {
            include *
            autoLayout
        }
        updateViews
    }
}

